import json, hashlib, pathlib, datetime, os
R=pathlib.Path(__file__).resolve().parents[4]
O=pathlib.Path(__file__).resolve().parent
cards=json.loads((R/'research/progress/r2-preflight-repair/SOURCE_CARDS.json').read_text())
now=datetime.datetime.now(datetime.timezone.utc)
def item(id,page,loc,quote,meaning,kind='operative'):
 return dict(id=id,pdf_page=page,location=loc,quote=quote,classification=kind,source_first_reading=meaning)
cases=[]
def case(eo,title,date,printed,boundary,items,notes):
 c=next(c for c in cards if c['instrument_id']==eo)
 h=hashlib.sha256((R/c['raw_pdf']).read_bytes()).hexdigest()
 assert h==c['source_sha256']
 cases.append(dict(instrument_id=eo,title=title,signed_date=date,printed_pages=printed,raw_pdf=c['raw_pdf'],expected_sha256=c['source_sha256'],observed_sha256=h,hash_match=True,listed_pdf_pages=c['pdf_pages'],rendered_and_visually_inspected_pages=c['pdf_pages'],render_command='pdftoppm -f PAGE -l PAGE -r 130 -png -singlefile RAW_PDF source-review/EO_NUMBER-pPAGE',visual_tool='view_image, full page images, all listed pages',source_boundary=boundary,command_inventory=items,qualifications_and_ambiguities=notes))
